#include <RenderBackend.h>
#include <cstdio>
#include <cstdlib>
#include <cstring>
#include <chrono>
#include <memory>
int main(int argc,char**argv){SDL_Init(SDL_INIT_VIDEO);if(argc>1)SDL_SetHint(SDL_HINT_RENDER_DRIVER,argv[1]);for(bool gpu:{false,true}){setenv("GLOB2_DISABLE_GPU_TEXTURE_PREPARATION",gpu?"":"1",1);auto*w=SDL_CreateWindow("SDL preparation probe",256,256,SDL_WINDOW_HIDDEN);auto backend=GAGCore::makeSDLRenderBackend(w,256,256);auto*r=SDL_GetRenderer(w);printf("driver=%s mode=%s\n",SDL_GetRendererName(r),gpu?"gpu":"cpu");auto*s=SDL_CreateSurface(256,256,SDL_PIXELFORMAT_ARGB8888);for(int a=0;a<256;++a)for(int c=0;c<256;++c)((Uint32*)((Uint8*)s->pixels+a*s->pitch))[c]=(a<<24)|(c<<16)|((255-c)<<8)|c;auto*t=SDL_CreateTexture(r,SDL_PIXELFORMAT_ARGB8888,SDL_TEXTUREACCESS_TARGET,256,256);SDL_SetRenderTarget(r,t);SDL_SetRenderDrawColor(r,0,0,0,0);SDL_RenderClear(r);backend->prepareTexture(s,s,1,true);SDL_Rect src{0,0,256,256};SDL_FRect dst{0,0,256,256};backend->blitLinear(s,s,1,src,dst,255);auto*out=backend->capture();for(int a=0;a<256;++a)for(int c=0;c<256;++c){Uint32 p;memcpy(&p,(Uint8*)out->pixels+a*out->pitch+c*4,4);Uint8 rr,g,b,aa;SDL_GetRGBA(p,SDL_GetPixelFormatDetails(out->format),nullptr,&rr,&g,&b,&aa);if(rr!=(a*c+127)/255||g!=(a*(255-c)+127)/255||b!=rr||aa!=a){printf("mismatch a=%d c=%d got=%d,%d,%d,%d\n",a,c,rr,g,b,aa);return 3;}}printf("all 65536 alpha/channel combinations match\n");SDL_DestroySurface(out);SDL_SetRenderTarget(r,nullptr);SDL_DestroyTexture(t);SDL_DestroySurface(s);backend->reset();for(int size:{128,256,512,1024}){s=SDL_CreateSurface(size,size,SDL_PIXELFORMAT_ARGB8888);Uint32 random=42;for(int y=0;y<size;++y)for(int x=0;x<size;++x){random^=random<<13;random^=random>>17;random^=random<<5;((Uint32*)((Uint8*)s->pixels+y*s->pitch))[x]=random;}double submit=0,total=0;for(int n=-4;n<32;++n){auto a=std::chrono::steady_clock::now();backend->prepareTexture(s,s,n+5,true);auto b=std::chrono::steady_clock::now();src={0,0,size,size};backend->blitLinear(s,s,n+5,src,dst,255);out=backend->capture();if(!out)return 4;auto c=std::chrono::steady_clock::now();if(n>=0){submit+=std::chrono::duration<double,std::milli>(b-a).count();total+=std::chrono::duration<double,std::milli>(c-a).count();}SDL_DestroySurface(out);}printf("%s,%d,%.4f,%.4f\n",gpu?"gpu":"cpu",size,submit/32,total/32);backend->forget(s);SDL_DestroySurface(s);}backend.reset();SDL_DestroyWindow(w);}SDL_Quit();}
